#include "PluginProcessor.h"
#include "ControlBridge.h"
#include <stdexcept>
namespace {
juce::var obj(std::initializer_list<std::pair<const char*,juce::var>> values){auto* o=new juce::DynamicObject;for(auto& value:values)o->setProperty(value.first,value.second);return juce::var(o);}
int integer(const juce::var& v,int minimum,int maximum){if(!(v.isInt()||v.isInt64()||v.isDouble()))throw std::runtime_error("Expected numeric integer");double n=(double)v;if(!std::isfinite(n)||n!=std::floor(n)||n<minimum||n>maximum)throw std::runtime_error("Integer out of range");return (int)n;}
float number(const juce::var& v,float minimum,float maximum){if(!(v.isInt()||v.isInt64()||v.isDouble()))throw std::runtime_error("Expected numeric value");double n=(double)v;if(!std::isfinite(n)||n<minimum||n>maximum)throw std::runtime_error("Number out of range");return (float)n;}
void fields(const juce::var& args,juce::StringArray allowed){if(!args.isObject())throw std::runtime_error("Arguments must be an object");for(auto& entry:args.getDynamicObject()->getProperties())if(!allowed.contains(entry.name.toString()))throw std::runtime_error("Unknown argument");}
}
void FieldProcessor::enableControl(bool enable){if(enable&&!controlBridge)controlBridge=std::make_unique<ControlBridge>([this](const juce::String& op,const juce::var& args){return invokeControl(op,args);});else if(!enable)controlBridge.reset();}
juce::String FieldProcessor::controlEndpoint() const {return controlBridge?controlBridge->descriptor().getFullPathName():juce::String{};}
juce::var FieldProcessor::invokeControl(const juce::String& op,const juce::var& args){
 if(!juce::MessageManager::getInstance()->isThisTheMessageThread())throw std::runtime_error("Control calls require message thread");
 if(op=="get_state"){fields(args,{});const juce::ScopedLock lock(engineLock);return obj({{"project",projectName},{"sequencer",value("sequencer")},{"sequence_on",value("sequenceOn")},{"tempo",value("tempo")},{"effective_tempo",engine.parameters().tempo},{"tape_speed",engine.parameters().tapeSpeed},{"clock_locked",clockLocked.load()},{"clock_mode",value("midiClockMode")},{"clock_relay",value("midiClockRelay")},{"tape_tempo_link",value("tempoTapeLink")},{"held_notes",engine.heldNoteCount()},{"active_voices",engine.activeVoiceCount()},{"playing",engine.playing()},{"recording",engine.recording()},{"playhead",engine.positionSeconds()},{"length",engine.sequenceLength()},{"step",engine.currentSequenceStep()},{"finger_bank",engine.fingerPattern()}});}
 if(op=="list_parameters"){fields(args,{"query","limit"});auto query=args["query"].toString();int limit=args.hasProperty("limit")?integer(args["limit"],1,64):16;juce::Array<juce::var> entries;for(int i=0;i<P_count&&entries.size()<limit;++i){auto* p=rawTargets[(size_t)i];if(query.isNotEmpty()&&!parameterIds[(size_t)i].containsIgnoreCase(query)&&!p->getName(100).containsIgnoreCase(query))continue;auto range=p->getNormalisableRange();juce::Array<juce::var> choices;if(auto* choice=dynamic_cast<juce::AudioParameterChoice*>(p))for(auto label:choice->choices)choices.add(label);entries.add(obj({{"id",parameterIds[(size_t)i]},{"name",p->getName(100)},{"value",value(parameterIds[(size_t)i])},{"min",range.start},{"max",range.end},{"choices",choices}}));}return entries;}
 if(op=="set_parameters"){fields(args,{"values"});auto values=args["values"];if(!values.isObject()||values.getDynamicObject()->getProperties().size()>64)throw std::runtime_error("values must contain at most 64 parameters");std::vector<std::pair<juce::String,float>> checked;for(auto& item:values.getDynamicObject()->getProperties()){auto id=item.name.toString();auto* p=parameters.getParameter(id);if(!p)throw std::runtime_error("Unknown parameter ID");auto r=p->getNormalisableRange();float n=number(item.value,r.start,r.end);if(p->isDiscrete()&&n!=std::floor(n))throw std::runtime_error("Discrete parameter requires integer");checked.emplace_back(id,n);}for(auto& item:checked)setValue(item.first,item.second);return obj({{"updated",(int)checked.size()}});}
 if(op=="get_sequence"){
  fields(args,{"start","count","bank"});int start=args.hasProperty("start")?integer(args["start"],0,998):0,count=args.hasProperty("count")?integer(args["count"],1,128):16,bank=args.hasProperty("bank")?integer(args["bank"],0,15):-1;const juce::ScopedLock lock(engineLock);int maximum=bank<0?999:32;juce::Array<juce::var> steps;
  for(int i=start;i<std::min(maximum,start+count);++i){juce::Array<juce::var> notes;const auto& chord=bank<0?engine.sequenceNotes(i):engine.fingerNotes(bank,i);for(int n=0;n<128;++n)if(chord[(size_t)n])notes.add(n);steps.add(obj({{"index",i},{"note",bank<0?engine.sequenceStep(i):engine.fingerStep(bank,i)},{"notes",notes},{"velocity",bank<0?engine.sequenceVelocity(i):engine.fingerVelocity(bank,i)}}));}
  return obj({{"length",bank<0?engine.sequenceLength():engine.fingerLength(bank)},{"steps",steps}});
 }
 if(op=="set_sequence"){
  fields(args,{"steps","length","bank"});int bank=args.hasProperty("bank")?integer(args["bank"],0,15):-1,maximum=bank<0?999:32;int length=args.hasProperty("length")?integer(args["length"],1,maximum):0;auto* steps=args["steps"].getArray();if(!steps||steps->size()>maximum)throw std::runtime_error("steps must be a bounded array");
  struct Step{int i;std::vector<int> notes;float velocity;};std::vector<Step> checked;
  for(auto& step:*steps){fields(step,{"index","note","notes","velocity"});if(step.hasProperty("note")==step.hasProperty("notes"))throw std::runtime_error("Choose note or notes per step");Step result{integer(step["index"],0,maximum-1),{},step.hasProperty("velocity")?number(step["velocity"],0,1):.8f};if(step.hasProperty("note")){int n=integer(step["note"],-1,127);if(n>=0)result.notes.push_back(n);}else{auto* notes=step["notes"].getArray();if(!notes||notes->size()>8)throw std::runtime_error("At most eight notes per chord");for(auto n:*notes)result.notes.push_back(integer(n,0,127));}checked.push_back(std::move(result));}
  const juce::ScopedLock lock(engineLock);for(auto& step:checked){if(bank<0)engine.setSequenceStep(step.i,-1,step.velocity);else engine.setFingerStep(bank,step.i,-1,step.velocity);for(int n:step.notes)if(bank<0)engine.setSequenceNote(step.i,n,true);else engine.setFingerNote(bank,step.i,n,true);}if(length){if(bank<0)engine.setSequenceLength(length);else engine.setFingerLength(bank,length);}++controlRevision;return obj({{"updated",(int)checked.size()}});
 }
 if(op=="transport"){fields(args,{"action"});auto action=args["action"].toString();if(!juce::StringArray{"play","stop","rewind","panic"}.contains(action))throw std::runtime_error("Unsupported transport action");transport(action);return obj({{"action",action}});}
 if(op=="notes"){fields(args,{"notes","velocity","on"});auto* notes=args["notes"].getArray();if(!notes||notes->size()>16||!args["on"].isBool())throw std::runtime_error("Use up to 16 MIDI notes and boolean on");std::vector<int> checked;for(auto n:*notes)checked.push_back(integer(n,0,127));float velocity=args.hasProperty("velocity")?number(args["velocity"],0,1):.8f;for(int note:checked){bool sent=(bool)args["on"]?keyboard.noteOn(keyboardMidiChannel(),note,velocity):keyboard.noteOff(keyboardMidiChannel(),note,0);if(!sent)throw std::runtime_error("Keyboard queue full; panic requested");}return obj({{"queued",(int)checked.size()}});}

 if(op=="manual_step"){fields(args,{});if(value("sequencer")!=2||value("seqManual")<.5f)throw std::runtime_error("Manual Endless mode must be enabled");const juce::ScopedLock lock(engineLock);updateEngine();engine.advanceSequence();return obj({{"step",engine.currentSequenceStep()}});}
 throw std::runtime_error("Unknown control operation");
}
